q2_part(P) :- brass_part(P), partsupp(P,S), european_supplier(S).
q2 :- q2_part(_).
building_customer(C) :- customer(C,_,building).
early_order(O,C) :- orders(O,C,_,Date,_), Date < 19950315.
shipped_late(O) :- lineitem(O,_,_,_,_,_,_,_,Ship,_,_,_,_), Ship > 19950315.
q3_order(O) :- building_customer(C), early_order(O,C), shipped_late(O).
q3 :- q3_order(_).
late_lineitem(O) :- lineitem(O,_,_,_,_,_,_,_,_,Commit,Receipt,_,_), Commit < Receipt.
q4_priority(Pri) :- orders(O,_,_,Date,Pri), Date >= 19930701, Date < 19931001, late_lineitem(O).
q4 :- q4_priority(_).
discounted(O,L) :- lineitem(O,L,_,_,Qty,Disc,_,_,Ship,_,_,_,_), Ship >= 19940101, Ship < 19950101, Disc >= 5, Disc =< 7, Qty < 24.
q6 :- discounted(_,_).
supplier_nation(S,Name) :- supplier(S,N), nation(N,Name,_).
customer_nation(C,Name) :- customer(C,N,_), nation(N,Name,_).
shipping(S,C) :- lineitem(O,_,_,S,_,_,_,_,Ship,_,_,_,_), Ship >= 19950101, Ship =< 19961231, orders(O,C,_,_,_).
q7_volume(N1,N2) :- q7_pair(N1,N2), supplier_nation(S,N1), shipping(S,C), customer_nation(C,N2).
q7 :- q7_volume(_,_).
q7_pair(france,germany).
q7_pair(germany,france).
returned_order(O) :- lineitem(O,_,_,_,_,_,r,_,_,_,_,_,_).
q10_customer(C) :- orders(O,C,_,Date,_), Date >= 19931001, Date < 19940101, returned_order(O), customer_nation(C,_).
q10 :- q10_customer(_).
german_supplier(S) :- supplier(S,N), nation(N,germany,_).
q11_part(P) :- partsupp(P,S), german_supplier(S).
q11 :- q11_part(_).
q12_lineitem(O,Mode) :- lineitem(O,_,_,_,_,_,_,_,Ship,Commit,Receipt,_,Mode), q12_mode(Mode), Commit < Receipt, Ship < Commit, Receipt >= 19940101, Receipt < 19950101.
q12_shipmode(Mode) :- orders(O,_,_,_,_), q12_lineitem(O,Mode).
q12 :- q12_shipmode(_).
q12_mode(mail).
q12_mode(ship).
shipped_in_september(P) :- lineitem(_,_,P,_,_,_,_,_,Ship,_,_,_,_), Ship >= 19950901, Ship < 19951001.
q14 :- shipped_in_september(P), part(P,_,_,_,_,_,_,_,_,_).
revenue(S) :- lineitem(_,_,_,S,_,_,_,_,Ship,_,_,_,_), Ship >= 19960101, Ship < 19960401.
q15 :- supplier(S,_), revenue(S).
q17_part(P) :- part(P,_,_,brand23,_,_,_,_,med,box).
q17 :- lineitem(_,_,P,_,_,_,_,_,_,_,_,_,_), q17_part(P).
query(q2).
query(q3).
